{
  "name": "mac_rx_timeout_check",
  "confidence": "medium",
  "docstring": "Handles RX timeout bookkeeping for a packet descriptor by clearing a MAC RX timeout IRQ when stale, adjusting the descriptor timeout from PHY status, and resetting/relinking the descriptor.",
  "subsystem": "mac",
  "var_renames": {
    "v1": "rx_pkt",
    "v2": "timeout_ticks"
  },
  "struct_hints": [
    {
      "offset": 16,
      "meaning": "descriptor status byte set to 2 on completion"
    },
    {
      "offset": 48,
      "meaning": "16-bit RX timeout/duration counter decremented based on PHY status"
    },
    {
      "offset": 84,
      "meaning": "32-bit PHY RX status field; bits masked by 0x7C select the timeout decrement amount"
    },
    {
      "offset": 156,
      "meaning": "status/flag byte cleared during descriptor completion"
    }
  ]
}
